import{t as e}from"./jsx-runtime-lw2jiZar.js";import{A as t,C as n,E as r,M as i,N as a,O as o,P as s,S as c,k as l,l as u,n as d,o as f,p,t as m,w as h}from"./shared-DP9JVsk0.js";import{t as g}from"./database-LLH4Psoh.js";import{t as _}from"./folder-open-tDtfkG-H.js";import{t as v}from"./settings-CJ1OvapJ.js";var y=e(),b=`Этап 4 · Блок 16 · Надёжность, запросы и передача работающего Planner`;function x({module:e}){return(0,y.jsxs)(a,{children:[(0,y.jsx)(i,{variant:`project`,chip:e??b,title:`80. Передача DB Planner`,intro:`Проверим, сможет ли новый разработчик получить тот же Planner из чистой копии и пройти документированный путь до работающих тестов, API и CLI.`,tags:[{icon:(0,y.jsx)(_,{size:14}),label:`чистый checkout`},{icon:(0,y.jsx)(v,{size:14}),label:`воспроизводимая среда`},{icon:(0,y.jsx)(g,{size:14}),label:`одна SQLite`}]}),(0,y.jsxs)(s,{number:`00`,title:`От принятого продукта к точной передаче`,children:[(0,y.jsx)(o,{children:`Точкой входа должен быть принятый результат занятия 79. Теперь проверим его глазами человека, у которого нет нашей рабочей папки, старой виртуальной среды и уже созданной базы.`}),(0,y.jsx)(l,{variant:`connected`,items:[{title:`Точка старта`,description:`На вход нужен принятый после занятия 79 синхронный Planner на SQLite, его API, CLI и проверки. До подтверждения B79 это условие остаётся блокером. Git, venv, requirements и настройки уже встречались в главе.`},{title:`Новый вопрос`,description:`Какие локальные файлы и настройки могут помочь привычному запуску, но исчезнут у разработчика в чистой копии?`},{title:`Результат`,description:`Мы проверим документацию на отдельном checkout и передадим следующей главе воспроизводимый Planner с честно обозначенными границами.`}]}),(0,y.jsx)(`p`,{children:`Сначала зафиксируем ревизию, которую действительно приняли, затем пройдём инструкцию без старого окружения. Это применение знакомых Git, Python, настроек и SQLite в новом контексте. Мы не начинаем заново проектировать хранилище и не считаем один удачный запуск доказательством для другого компьютера.`})]}),(0,y.jsxs)(s,{number:`01`,title:`Чистая копия начинается с известного checkpoint`,children:[(0,y.jsx)(o,{children:`Рабочая папка содержит больше, чем Git commit. В ней могут оставаться незакоммиченные правки, неотслеживаемые файлы, игнорируемый .env, старая .venv и база, которую приложение нашло при прошлом запуске.`}),(0,y.jsx)(`p`,{children:"Checkout выбранной ревизии показывает состояние файлов, зафиксированное в конкретном commit. Чистая копия отделяет это состояние от локальных помощников разработчика. Для передачи нам нужна именно ревизия принятого результата занятия 79. Текущая ветка, имя `main` и номер занятия сами по себе её не определяют. Если сначала взять более ранний commit, даже идеальная инструкция запустит не тот продукт."}),(0,y.jsx)(`p`,{children:`Представим закрытый набор для лабораторной работы. Внутри есть перечень деталей и точный порядок сборки, но рядом нельзя незаметно подложить инструмент из личного ящика. Commit задаёт набор исходных деталей, а чистый checkout помогает увидеть, чего в нём на самом деле не хватает. Сравнение ограничено: репозиторий хранит исходные файлы, но не обязан содержать установленный Python, приватный .env или рабочую базу.`}),(0,y.jsx)(`p`,{children:"Перед запуском посмотрим на состав копии. `git status --short` показывает незакоммиченные и неотслеживаемые изменения в текущем checkout, а `git ls-files` перечисляет то, что уже включено в репозиторий. Правило `.gitignore` обычно не добавляет локальные файлы, но не удаляет ранее отслеживаемый файл. Поэтому отсутствие `.env` в новом checkout и отсутствие секретов среди tracked-файлов отвечают на разные вопросы. Мы проверяем оба, не печатая значения настроек."}),(0,y.jsx)(t,{rows:[[(0,y.jsx)(`code`,{children:`tracked`}),`Версия файла входит в выбранный commit.`],[(0,y.jsx)(`code`,{children:`untracked`}),`Файл есть в папке, но его нет в этой версии репозитория.`],[(0,y.jsx)(`code`,{children:`ignored`}),`Git обычно скрывает локальный файл от новых добавлений, но ignore не удаляет уже tracked-файл.`],[(0,y.jsx)(`code`,{children:`clean checkout`}),`Отдельная копия позволяет проверить только состояние выбранной ревизии и явно созданную среду.`]]}),(0,y.jsx)(c,{statement:`Если проект запускается в привычной папке, его инструкции уже доказанно воспроизводимы на чистой копии.`,isTrue:!1,explanation:`Привычная папка могла предоставить .env, установленный пакет, локальную базу или незакоммиченный файл. Для проверки нужна новая копия точной принятой ревизии.`})]}),(0,y.jsxs)(s,{number:`02`,title:`README задаёт проверяемый маршрут`,children:[(0,y.jsx)(o,{children:`README помогает новому человеку пройти путь от получения кода до наблюдаемого результата. Общая фраза «установить зависимости и запустить» не указывает ни команды, ни ожидаемое состояние после каждого шага.`}),(0,y.jsx)(`p`,{children:`Для каждого действия нам нужны четыре опоры: папка, из которой запускается команда, выбранный интерпретатор, входные настройки и понятный результат. Если тесты требуют отдельного файла зависимостей, README устанавливает именно его. Если SQLite создаётся отдельной командой, перед первым обращением к приложению это явно написано. Если запуск API открывает локальный адрес, инструкция называет его и объясняет, как остановить процесс.`}),(0,y.jsx)(`p`,{children:`README похож на маршрут с остановками: название улицы без поворотов не доведёт нас до нужного места. Команда является поворотом, а проверяемый результат каждой остановки подтверждает, что мы ещё идём по правильному пути. Граница аналогии такая: текст документации ничего не выполняет сам. Его шаги нужно пройти в новой среде и сверить с настоящими файлами проекта.`}),(0,y.jsx)(`p`,{children:"В независимом примере проекта заметок инструкция сначала создаёт отдельную среду, затем устанавливает список зависимостей и запускает команду проверки. Успешный запуск только после ручной установки ещё одного пакета означает, что маршрут неполон. Аналогично наличие `requirements.txt` не доказывает, что он содержит инструменты тестирования или что README выбрал правильный файл."}),(0,y.jsx)(h,{title:`Восстанавливаем порядок проверки`,prompt:`Расставим части чистого запуска так, чтобы не использовать старое окружение и не запускать Planner до создания новой схемы.`,pieces:[{id:`checkout`,code:`Checkout принятой ревизии`,note:`код`},{id:`venv`,code:`Создать новую venv`,note:`интерпретатор проекта`},{id:`install`,code:`Установить requirements из README`,note:`пакеты проекта`},{id:`config`,code:`Задать адрес новой тестовой БД`,note:`локальная настройка`},{id:`tests`,code:`Запустить тесты из новой среды`,note:`изолированные проверки`},{id:`schema`,code:`Явно создать исходную схему`,note:`пустая SQLite`},{id:`interfaces`,code:`Проверить CLI и API на одном адресе`,note:`общая база`},{id:`restart`,code:`Запустить новый процесс и перечитать задачу`,note:`сохранённый результат`}],correctOrder:[`checkout`,`venv`,`install`,`config`,`tests`,`schema`,`interfaces`,`restart`],explanation:`Мы зафиксировали источник кода, зависимости и адрес до запуска. Тесты проходят в новой среде, схема создаётся явно, а новое чтение после запуска подтверждает сохранённое состояние.`,incorrectExplanation:`Сверим зависимости шагов: сначала нужны точная ревизия и новая среда, затем настройки и тесты. До работы API и CLI создадим схему, а сохранение проверим после нового процесса.`})]}),(0,y.jsxs)(s,{number:`03`,title:`Окружение и настройки не переносятся из старой папки`,children:[(0,y.jsx)(o,{children:`Чистая копия кода ещё не является чистой средой. Виртуальное окружение создаёт свой набор пакетов, а настройки процесса определяют, к какой базе обратится Planner.`}),(0,y.jsx)(`p`,{children:`Файл requirements фиксирует пакеты, необходимые проекту. Для запуска приложения могут быть нужны одни пакеты, а для тестов ещё и тестовые инструменты. Новая venv позволяет увидеть, описаны ли оба набора. Мы устанавливаем только объявленные проектом зависимости и не исправляем пропуск случайной установкой из глобального Python. Иначе повторная проверка на другой машине снова не сработает.`}),(0,y.jsx)(`p`,{children:"`.env.example` показывает имена параметров и безопасные примерные значения. Локальный `.env` содержит настройки конкретного запуска и не должен становиться способом передать секрет или личные данные. `DATABASE_URL` должен направлять тестовый запуск в отдельную новую SQLite. Унаследованная переменная PowerShell может иметь приоритет над файлом настроек, поэтому в чистой сессии мы проверяем выбранный адрес и не выводим содержимое секретов."}),(0,y.jsx)(`p`,{children:"Эти файлы похожи на карточки лаборатории: requirements перечисляет оборудование, `.env.example` сообщает, какие регуляторы нужны, а `.env` задаёт локальные значения. Но карточка не создаёт прибор и не изолирует измерение. За это отвечают установка зависимостей, проверка адреса и отдельный тестовый файл базы."}),(0,y.jsx)(`p`,{children:"Для SQLite важен и текущий каталог процесса. Относительный путь в `DATABASE_URL` может указывать на разные файлы, если CLI и API запущены из разных папок. README должен назвать корень проекта как рабочий каталог либо выбрать понятный адрес тестовой базы. Переменная среды текущего PowerShell-сеанса также может перекрыть `.env`; в новом терминале проверяем настройку снова. Мы сравниваем эффективное место хранения, а не только написанные рядом строки."}),(0,y.jsx)(p,{prompt:`Соединим каждый вход с тем, что он действительно подтверждает.`,leftTitle:`Вход`,rightTitle:`Назначение`,pairs:[{left:(0,y.jsx)(`code`,{children:`requirements-dev.txt`}),right:`Зависимости приложения и проверок`},{left:(0,y.jsx)(`code`,{children:`.env.example`}),right:`Имена настроек без личных значений`},{left:(0,y.jsx)(`code`,{children:`.env`}),right:`Локальные параметры конкретной среды`},{left:(0,y.jsx)(`code`,{children:`DATABASE_URL`}),right:`Адрес выбранной базы данных`},{left:(0,y.jsx)(`code`,{children:`tmp_path`}),right:`Изоляция базы для тестового сценария`}],explanation:`Requirements объявляют пакеты, пример среды объясняет настройку, локальный .env задаёт значения, DATABASE_URL указывает место хранения, а tmp_path помогает тесту создать отдельную базу.`})]}),(0,y.jsxs)(s,{number:`04`,title:`Исходная схема создаётся явно`,children:[(0,y.jsx)(o,{children:"Новый файл SQLite может быть пустым. До первого обращения к таблице `tasks` выполняется документированная команда исходной инициализации."}),(0,y.jsx)(`p`,{children:`Инициализация создаёт таблицы, описанные текущей исходной моделью, если их ещё нет. Повторный запуск на уже совпадающей схеме не является способом обновить её. Если колонки старой таблицы отличаются, нужна отдельная работа с изменением схемы. Здесь мы не изучаем Alembic, не очищаем заполненную базу и не включаем создание DDL при каждом старте API или CLI.`}),(0,y.jsx)(`p`,{children:`Можно представить пустую базу как новый блокнот с заранее заданными графами. Команда инициализации выдаёт чистый бланк. Если старый блокнот заполнен, печать нового бланка поверх него не переносит записи и не меняет структуру безопасно. Сравнение помогает отличить создание исходных таблиц от миграции уже используемых данных, но сама SQLite остаётся файлом, а не бумажным журналом.`}),(0,y.jsx)(`p`,{children:`Связанный маршрут проверки выглядит так. Каждая стрелка обозначает действие, а следующий узел становится доступен только после проверки результата предыдущего. Новая сессия или процесс нужны в конце, чтобы убедиться, что чтение получает сохранённое состояние из общей базы, а не только из объекта в памяти.`}),(0,y.jsx)(m,{caption:`От выбранной ревизии к сохранённой задаче`,orientation:`vertical`,children:(0,y.jsxs)(f,{label:`Последовательность чистого запуска`,orientation:`vertical`,children:[(0,y.jsx)(u,{title:`Принятая ревизия`,shape:`terminator`,children:(0,y.jsx)(`p`,{children:`Код после проверки занятия 79`})}),(0,y.jsx)(d,{label:`клонируем отдельно и создаём среду`}),(0,y.jsx)(u,{title:`Зависимости и настройки`,children:(0,y.jsx)(`p`,{children:`Новая venv и новый адрес SQLite`})}),(0,y.jsx)(d,{label:`явно готовим пустую базу`}),(0,y.jsx)(u,{title:`Исходная схема`,shape:`database`,children:(0,y.jsx)(`p`,{children:`Таблица tasks создана штатной командой`})}),(0,y.jsx)(d,{label:`запускаем тесты и оба интерфейса`}),(0,y.jsx)(u,{title:`API и CLI`,children:(0,y.jsx)(`p`,{children:`Одна тестовая база и согласованные результаты`})}),(0,y.jsx)(d,{label:`перезапускаем и читаем снова`}),(0,y.jsx)(u,{title:`Проверенная передача`,shape:`terminator`,children:(0,y.jsx)(`p`,{children:`Задача сохранена, ограничение следующей главы названо`})})]})}),(0,y.jsx)(`p`,{children:"Если какой-то переход возможен только благодаря старой `.venv`, готовой таблице или неописанному значению `DATABASE_URL`, схема помогает найти скрытый вход. Она показывает порядок доказательства, а не обещает, что любой выбранный commit уже принят или что создание таблиц обновляет несовместимую схему."})]}),(0,y.jsxs)(s,{number:`05`,title:`Два интерфейса проверяют одно состояние`,children:[(0,y.jsx)(o,{children:`API и CLI являются разными входами к общему Planner. Сквозной сценарий проверяет не два отдельных успешных экрана, а сохранённые изменения через одну базу и новое чтение.`}),(0,y.jsx)(`p`,{children:`Создадим тестовую задачу через API, найдём её CLI-командой, изменим статус через CLI и перечитаем через API. Затем перезапустим один из процессов и повторим чтение. Новый процесс получает новую Session и обращается к базе заново. Если оба интерфейса случайно используют разные SQLite-файлы, каждый может выглядеть исправным, хотя общей истории у них нет.`}),(0,y.jsx)(`p`,{children:"В HTTP-ответе могут отсутствовать внутренние `tags`. Это часть действующего публичного контракта. Поэтому внутренние данные сверяются отдельным чтением тестовой базы или готовой проверкой. Используем CLI только если его фактический вывод содержит tags. Мы не добавляем endpoint только ради проверки. Обычные HTTP-ответы и прежние CLI-команды остаются понятными, а тесты не подключаются к рабочим файлам."}),(0,y.jsx)(n,{code:`README говорит:
1. Создайте новую venv.
2. Установите только requirements.txt.
3. Запустите pytest из этой venv.`,question:`Какой дефект делает этот маршрут ненадёжным, если pytest объявлен в requirements-dev.txt?`,options:[`Команда тестирования требует dev-зависимость, которую инструкция не установила.`,`README вообще не должен содержать команд запуска.`,`Новая venv обязана заранее содержать пакеты глобального Python.`],correctIndex:0,explanation:`В чистой venv команды видят только установленные в ней пакеты. Если pytest объявлен в requirements-dev.txt, README должен установить этот файл перед запуском тестов.`,fix:`Сверим команду установки с тем файлом зависимостей, где проект объявляет тестовые инструменты.`}),(0,y.jsx)(r,{tone:`info`,children:"Git ignore помогает не добавлять локальную базу и `.env` в будущем. Если файл уже tracked, одной новой строкой ignore он из репозитория не исчезает. Проверим состав индекса отдельно и не будем печатать секреты в терминал, отчет или историю команд."})]}),(0,y.jsxs)(s,{number:`06`,title:`Передаём точную границу следующей главы`,children:[(0,y.jsx)(o,{children:`Приёмка заканчивается проверенными фактами о коде, командах и ограничениях. Общее слово «готово» не сообщает, что именно сможет повторить следующий разработчик.`}),(0,y.jsx)(`p`,{children:`В handoff называем точную принятую ревизию, версии интерпретатора и зависимостей, команды настройки, инициализации, тестирования и запуска. Отдельно отмечаем, что фактически проверили, а что осталось вне проверки. Если тесты прошли, это подтверждает этот тестовый набор и эту среду. Сквозной сценарий подтверждает связь API и CLI. Ни то, ни другое не является проверкой production-развёртывания.`}),(0,y.jsx)(`p`,{children:`Короткая запись передачи должна позволить повторить проверку: полный SHA и источник его принятия, Python и установленные файлы зависимостей, команды и их фактические результаты, id контрольной задачи и чтение после перезапуска. Если шаг не выполнялся, так и пишем. Нельзя заменять результат тестов старой цифрой из README или выдавать запланированный шаг за состоявшийся.`}),(0,y.jsx)(`p`,{children:`Следующая глава получает синхронный Planner с одной исходной таблицей задач, SQL-репозиторием, API, CLI, проверками и явным созданием схемы. Изменение уже заполненной схемы ещё не изучалось. Пользователь, владение задачами и авторизация тоже остаются будущими темами. Cookie настроек интерфейса не превращается в защищённый вход в систему.`}),(0,y.jsx)(c,{statement:`Повторный вызов create_all доказывает, что заполненную таблицу безопасно изменить под новую модель.`,isTrue:!1,explanation:`Создание отсутствующих таблиц не обновляет существующие колонки. Несовпадение схемы требует отдельной диагностики и будущего механизма миграции.`}),(0,y.jsx)(`p`,{children:`Наконец, передача не требует коммита, публикации или развёртывания без отдельного задания. Мы сохраняем изменения в нужных файлах курса, а внешнюю ревизию используем как проверяемую опору. Секреты, рабочая SQLite и персональные задачи остаются локальными.`})]}),(0,y.jsxs)(s,{number:`07`,title:`Что мы будем делать в практике`,children:[(0,y.jsx)(o,{children:`Теперь соединим привычные команды в проверку, которая показывает, что проект переживает перенос в чистую копию.`}),(0,y.jsx)(l,{variant:`connected`,items:[{title:`Зафиксируем вход`,description:`Подтвердим B79 источником и кодом. Если его нет, зафиксируем блокер; если есть, проверим commit в отдельном checkout.`},{title:`Пройдём документацию`,description:`Сверим зависимости, настройки и команду исходной схемы, затем выполним тесты и запуск по README.`},{title:`Подтвердим передачу`,description:`Проверим задачу между API и CLI, перечитаем после нового процесса и запишем проверенную границу следующей главы.`}]}),(0,y.jsx)(r,{tone:`info`,children:`Входная проверка обязательна. Если принятый B79 и соответствующий полный SHA не подтверждены журналом и кодом, фиксируем блокер и останавливаем практический прогон. Более ранний checkpoint или текущая ветка не заменяют этот вход.`}),(0,y.jsx)(t,{rows:[[`Источник`,`Есть подтверждённый B79 и чистый checkout точного SHA.`],[`Инструкция`,`README-команды совпадают с файлами и наблюдаемыми результатами.`],[`Среда и схема`,`Новая venv и SQLite; явная и повторная инициализация сохраняет контрольную запись.`],[`Два интерфейса`,`Одна задача проходит API и CLI, затем читается новым процессом.`],[`Передача`,`Записаны проверенные факты и границы, без локальных данных и секретов.`]]}),(0,y.jsx)(`p`,{children:`Практика не предполагает новую реализацию CRUD. Если README уже точно описывает проект, это тоже результат: изменения в документации ради формального diff не нужны. Важно пройти все команды из чистого окружения и зафиксировать их фактический результат. Рабочая база и личные данные не используются.`}),(0,y.jsx)(`p`,{children:`Завершим короткой регрессией прежних API и CLI-возможностей, проверим отсутствие JSON-fallback и перечислим ограничения. Для запуска нужен точный принятый checkpoint после занятия 79. Более ранняя ревизия не доказывает передачу финального продукта.`})]})]})}export{x as Lesson80};